PRAGMA foreign_keys = ON;

-- BOS_CYO 2026-09-13: Dermo Leker product-photo refresh from approved Canva 1x1-clean-v2 assets.
-- Scope: store_dermo + category Leker only.
-- 17 exact matched Canva assets are applied; every other Dermo Leker image_data is cleared
-- so stale/old product photos do not remain visible.
-- Non-Leker products and every other store remain untouched.
-- DOC-IMPACT: NOT_REQUIRED — store-scoped product master media refresh only; no API/schema/contract behavior change.

CREATE TABLE dermo_leker_product_images_0086 (
  product_name TEXT PRIMARY KEY,
  image_data TEXT NOT NULL CHECK (image_data LIKE 'data:image/webp;base64,%')
);

INSERT INTO dermo_leker_product_images_0086 (product_name, image_data) VALUES
  ('Leker Susu Coklat', 'data:image/webp;base64,'),
  ('Leker Susu Vanila', 'data:image/webp;base64,'),
  ('Leker Meses', 'data:image/webp;base64,'),
  ('Leker Keju', 'data:image/webp;base64,'),
  ('Leker Cappucino', 'data:image/webp;base64,');

CREATE TABLE dermo_leker_product_images_guard_0086 (
  ok INTEGER NOT NULL CHECK (ok = 1)
);

INSERT INTO dermo_leker_product_images_guard_0086 (ok)
SELECT CASE WHEN
  (SELECT COUNT(*) FROM products WHERE store_id = 'store_dermo' AND category = 'Leker') = 73
  AND (SELECT COUNT(*) FROM dermo_leker_product_images_0086) = 17
  AND (
    SELECT COUNT(*)
    FROM dermo_leker_product_images_0086 i
    JOIN products p
      ON p.store_id = 'store_dermo'
     AND p.category = 'Leker'
     AND p.name = i.product_name
  ) = 17
THEN 1 ELSE 0 END;

DROP TABLE dermo_leker_product_images_guard_0086;

UPDATE products
SET image_data = '',
    updated_at = CURRENT_TIMESTAMP
WHERE store_id = 'store_dermo'
  AND category = 'Leker'
  AND name NOT IN (SELECT product_name FROM dermo_leker_product_images_0086);

UPDATE products
SET image_data = (
      SELECT i.image_data
      FROM dermo_leker_product_images_0086 i
      WHERE i.product_name = products.name
    ),
    updated_at = CURRENT_TIMESTAMP
WHERE store_id = 'store_dermo'
  AND category = 'Leker'
  AND name IN (SELECT product_name FROM dermo_leker_product_images_0086);

CREATE TABLE dermo_leker_product_images_verify_0086 (
  ok INTEGER NOT NULL CHECK (ok = 1)
);

INSERT INTO dermo_leker_product_images_verify_0086 (ok)
SELECT CASE WHEN
  (
    SELECT COUNT(*)
    FROM products p
    JOIN dermo_leker_product_images_0086 i
      ON i.product_name = p.name
    WHERE p.store_id = 'store_dermo'
      AND p.category = 'Leker'
      AND p.image_data = i.image_data
  ) = 17
  AND (
    SELECT COUNT(*)
    FROM products
    WHERE store_id = 'store_dermo'
      AND category = 'Leker'
      AND COALESCE(image_data, '') = ''
  ) = 56
THEN 1 ELSE 0 END;

DROP TABLE dermo_leker_product_images_verify_0086;
DROP TABLE dermo_leker_product_images_0086;
